package org.sleepwell.app;
import android.content.Context;import android.net.Uri;import java.io.*;import java.security.*;import java.util.*;import java.util.function.BooleanSupplier;
/** Unique immutable fsynced files; only an explicitly returned URI gets a temporary read grant. */
final class SleepSummaryFiles {
 static final int MAX_BYTES=1024*1024,MAX_FILES=32;private static final Object LOCK=new Object();
 static File directory(Context context)throws IOException{File cache=context.getCacheDir().getCanonicalFile(),root=new File(cache,"shared-sleep-summaries").getCanonicalFile();if(!cache.equals(root.getParentFile())||!root.isDirectory()&&!root.mkdirs())throw new IOException("Summary storage unavailable.");return root;}
 static final class Snapshot {final File file;final String sha;final SleepSummary.Data data;volatile boolean shared;Snapshot(File file,String sha,SleepSummary.Data data){this.file=file;this.sha=sha;this.data=data;}Uri uri(Context app){return androidx.core.content.FileProvider.getUriForFile(app,app.getPackageName()+".sleep-summary",file);}void discard(){if(!shared)file.delete();}void verify(BooleanSupplier active)throws Exception{long age=System.currentTimeMillis()-file.lastModified();if(!file.isFile()||file.length()!=data.bytes.length||age<0||age>SleepSummaryFileProvider.AGE)throw new IOException("This reviewed summary expired. Prepare it again.");MessageDigest hash=MessageDigest.getInstance("SHA-256");long count=0;try(InputStream input=new FileInputStream(file)){byte[] bytes=new byte[8192];for(int n;(n=input.read(bytes))!=-1;){if(!active.getAsBoolean())throw new IOException("Sharing cancelled.");count+=n;if(count>data.bytes.length)throw new IOException("The reviewed summary changed.");hash.update(bytes,0,n);}}if(count!=data.bytes.length||!NightAudioArchive.hash(hash.digest()).equals(sha))throw new IOException("The reviewed summary changed. Prepare it again.");}}
 static Snapshot stage(Context app,SleepSummary.Data data,BooleanSupplier active)throws Exception{if(data.bytes.length>MAX_BYTES)throw new IOException("The summary exceeds 1 MiB. Choose a shorter period.");synchronized(LOCK){File root=directory(app);File[] old=root.listFiles();if(old==null||old.length>MAX_FILES*2)throw new IOException("Summary cache needs attention. Try again after old documents expire.");int count=0;long now=System.currentTimeMillis();for(File file:old){if(!file.isFile()||!file.getCanonicalFile().equals(file.getAbsoluteFile())||!file.getParentFile().getCanonicalFile().equals(root))throw new IOException("Summary cache unavailable.");if(file.getName().matches("(summary|pending)-[0-9a-f-]{36}\\.json")){if(now-file.lastModified()>SleepSummaryFileProvider.AGE){if(!file.delete())throw new IOException("Expired summary could not be removed.");}else count++;}else throw new IOException("Summary cache contains an unknown entry.");}if(count>=MAX_FILES)throw new IOException("32 recent summaries are already staged. They expire after 24 hours; existing client documents were kept.");File temporary=new File(root,"pending-"+UUID.randomUUID()+".json"),target=new File(root,"summary-"+UUID.randomUUID()+".json");boolean saved=false;try{try(FileOutputStream output=new FileOutputStream(temporary)){for(int at=0;at<data.bytes.length;at+=8192){if(!active.getAsBoolean())throw new IOException("Summary preparation cancelled.");output.write(data.bytes,at,Math.min(8192,data.bytes.length-at));}output.getFD().sync();}if(!active.getAsBoolean())throw new IOException("Summary preparation cancelled.");if(!temporary.renameTo(target))throw new IOException("Summary could not be staged.");saved=true;return new Snapshot(target,NightAudioArchive.hash(MessageDigest.getInstance("SHA-256").digest(data.bytes)),data);}finally{temporary.delete();if(!saved)target.delete();}}}
 private SleepSummaryFiles(){}
}
